def get_girth(n, edges):
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    min_cycle = float('inf')
    for i in range(n):
        # BFS to find shortest cycle containing i
        dist = [-1] * n
        dist[i] = 0
        queue = [i]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    queue.append(v)
                elif dist[v] >= dist[u]:
                    # Cycle found
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len < min_cycle:
                        min_cycle = cycle_len
    return min_cycle

def is_k_colorable(n, edges, k):
    # Simple backtracking coloring
    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    colors = [-1] * n
    def can_color(u):
        if u == n:
            return True
        for c in range(k):
            safe = True
            for v in adj[u]:
                if colors[v] == c:
                    safe = False
                    break
            if safe:
                colors[u] = c
                if can_color(u + 1):
                    return True
                colors[u] = -1
        return False
    return can_color(0)

